import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Alternative structure with minimal changes, focusing on I/O.
 */
public class Main {
  public static void main(String[] args) {
    InputStream input = System.in;
    OutputStream output = System.out;
    InputReader reader = new InputReader(input);
    PrintWriter writer = new PrintWriter(output);
    processInput(reader, writer);
    writer.close();
  }

  static void processInput(InputReader in, PrintWriter out) {
    int n = in.readInt();
    char[] s = in.readString().toCharArray();
    int[] ugliness = new int[n];
    for (int i = 0; i < n; i++) {
      ugliness[i] = -in.readInt();
    }
    // For demonstration, output the first character and sum of ugliness.
    int sumUgliness = 0;
    for (int val : ugliness) sumUgliness += val;
    out.println("First char: " + s[0]);
    out.println("Sum ugliness: " + sumUgliness);
  }

  static class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int pos, count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (count == -1) throw new InputMismatchException();
      if (pos >= count) {
        pos = 0;
        try {
          count = stream.read(buf);
        } catch (IOException e) {
          throw new InputMismatchException();
        }
        if (count <= 0) return -1;
      }
      return buf[pos++];
    }

    public int readInt() {
      int c = read();
      while (isSpace(c)) c = read();
      int sign = 1;
      if (c == '-') {
        sign = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') throw new InputMismatchException();
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      return res * sign;
    }

    public String readString() {
      int c = read();
      while (isSpace(c)) c = read();
      StringBuilder sb = new StringBuilder();
      do {
        if (Character.isValidCodePoint(c)) sb.appendCodePoint(c);
        c = read();
      } while (!isSpace(c));
      return sb.toString();
    }

    private boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
  }
}
